-- Arquivo: schema_corridas_outros_apps.sql
-- Go Ladies: corridas de outros apps, pra comparar com a Go Ladies (31/10/2026)
--
-- O que é: corridas feitas (ou só oferecidas) em outros apps de transporte,
-- guardadas como ESTUDO. Não é dinheiro da Go Ladies: não entra em viagens,
-- no Por motorista, no Livro-caixa nem no fechamento. O dinheiro que a Jú
-- recebe de outro app continua só no Livro-caixa (Caixinha Jú Motorista).
--
-- No CRM: Transporte › Financeiro do transporte › "Comparar com outros apps",
-- logo abaixo do Por motorista.
--   Parte 1 (Comparação): corridas feitas com o que a passageira pagou, ao
--   lado da linha Go Ladies, com as mesmas colunas do Por motorista.
--   Parte 2 (Relatos de outras motoristas): só o que a motorista recebe;
--   nunca somado com a parte 1.
--
-- Só número e bairro: a Uber avisa que print ou endereço fora do app viola os
-- termos dela. Por isso não tem campo de endereço nem de foto.
--
-- Já entra com 39 corridas: as 6 da Jú na Uber (15/10 e 28/10, da planilha
-- simulacoes_uber_poa.xlsx) e as 33 dos prints do grupo de motoristas de SC
-- (estudos/grupo-motoristas-sc/corridas-prints-2026-10-06.csv).
--
-- Só a equipe lê e edita (eh_staff).
--
-- Rodar uma vez em: Supabase (go-ladies-crm) → SQL Editor → New query →
-- colar tudo → Run. Pode rodar de novo sem duplicar nada.

create table if not exists public.corridas_outros_apps (
  id bigint generated by default as identity primary key,
  chave text unique,                 -- só das que vieram de planilha/print, pra não duplicar
  criado_em timestamptz not null default now(),
  criado_por uuid default auth.uid(),
  quem text not null default 'Jú'
    check (quem in ('Jú', 'Motorista parceira', 'Relato de grupo')),
  motorista_id bigint references public.motoristas(id) on delete set null,
  grupo text,                        -- de onde veio o relato (ex.: grupo de WhatsApp)
  tipo text not null default 'Feita' check (tipo in ('Feita', 'Oferta')),
  app text not null,                 -- Uber, 99, inDrive...
  categoria text,                    -- UberX, Pop, Comfort...
  data date,
  hora time,
  cidade text,
  bairro_saida text,
  bairro_chegada text,
  km numeric,
  minutos numeric,
  recebeu numeric,                   -- o que a motorista recebeu (com dinâmico, espera, promoção)
  pago_passageira numeric,           -- o que a passageira pagou; sem ele não dá a % do app
  dinamico numeric,
  espera numeric,
  vantagens numeric,                 -- promoção que o app paga à motorista (Vantagens Pro)
  ajuste numeric,                    -- "Ajuste de ganhos": o app completou
  fonte text,                        -- Detalhe da viagem, Resumo semanal, Print de grupo, Outro
  observacao text
);

comment on table public.corridas_outros_apps is
  'Estudo: corridas de outros apps pra comparar com a Go Ladies. Não é dinheiro da Go Ladies.';

create index if not exists corridas_outros_apps_data_idx on public.corridas_outros_apps (data);

alter table public.corridas_outros_apps enable row level security;

drop policy if exists "Staff administra corridas de outros apps" on public.corridas_outros_apps;
create policy "Staff administra corridas de outros apps" on public.corridas_outros_apps
  for all using (public.eh_staff()) with check (public.eh_staff());

revoke all on public.corridas_outros_apps from anon;

